import {TABLES,DOCUMENT_SCHEMA,clone,validateDocument,parseDocument,describeFarm,digest,nativeWorkbench,withNativeIds} from './document.js';
import {request,usesStaticHosting,PORTABLE_DOWNLOAD,PORTABLE_RELEASE} from './api.js';
import {mountOriginalUi,closeOriginalUi} from './original-ui.js';
import {installOriginalLanguageSync} from './original-language.js';
import {structuredKind,structuredInput,inputHelpMarkup,isFraction,editEncoded,reorderModules} from './input-controls.js';
import {fieldPair,fieldUnit,pathLabel,metricLabel,unitLabel,rememberPair,messageLabel,termPair} from './i18n.js';
import {esc,csv,download,fmt} from '../utils.js';

const STORAGE='farmsystem-farmdesign-native-v1';
const MODULES={Areas:['土地与轮作','Land and rotations'],FeedBalances:['分季饲料平衡','Seasonal feed balance'],FeedSelfSupply:['饲料自给','Feed self-supply'],OmBalance:['有机质平衡','Organic matter'],OmBalancePerHa:['每公顷有机质','Organic matter per ha'],Manures:['粪肥管理','Manure management'],NutrientFlows:['N/P/K/C 流','N/P/K/C flows'],NutrientFlowsPerHa:['每公顷元素流','Element flows per ha'],Labour:['农场与家庭劳动','Farm and family labour'],GHGs:['温室气体','Greenhouse gases'],Energy:['生物能','Bioenergy'],WaterUse:['水','Water'],EconResults:['农场经济核算','Farm economics'],ProductAmounts:['产品用途与进出口','Product destinations and trade'],BeddingUse:['垫料','Bedding'],ManureProd:['粪肥生产','Manure production'],Nutrition:['家庭营养与多样性','Human nutrition and diversity'],Budget:['经营与家庭预算','Farm and household budget'],NutrientFlowMatrix:['流网络','Flow networks'],Pesticides:['农药','Pesticides']};
const ID_FIELDS={FRM:'FrmID',ENV:'EnvID',ECN:'EcnID',ROT:'RotID',RCR:'RcrID',CRP:'CrpID',PRD:'PrdID',ANM:'AnmID',APR:'AprID',ARR:'ArrID',MAN:'ManID',FRT:'FrtID',CFR:'CfrID',CMR:'CmrID',PST:'PstID',CPR:'CprID',GRP:'GrpID',GCR:'GcrID',MCH:'MchID',BLD:'BldID',HHD:'HhdID',HMR:'HmrID',DRI:'DriID',DRF:'DrfID'};
const REF={RotID:['ROT','RotID'],CrpID:['CRP','CrpID'],AnmID:['ANM','AnmID'],RepID:['ANM','AnmID'],ManID:['MAN','ManID'],FrtID:['FRT','FrtID'],PstID:['PST','PstID'],GrpID:['GRP','GrpID'],HhdID:['HHD','HhdID']};
const GROUPS=[['FRM','ENV','ECN'],['ROT','RCR','CRP','PRD'],['ANM','APR','ARR','MAN'],['FRT','CFR','CMR','PST','CPR'],['HHD','HMR','DRI','DRF'],['MCH','BLD','GRP','GCR']];
let active=null,memory=null;

function flatten(value,path='',out=[]){if(typeof value==='number'||value===null||typeof value==='string'||typeof value==='boolean'){out.push({path,value});return out;}if(Array.isArray(value)){value.forEach((v,i)=>flatten(v,`${path}[${i}]`,out));return out;}if(value&&typeof value==='object')for(const [k,v]of Object.entries(value))flatten(v,path?path+'.'+k:k,out);return out;}
const isNumber=v=>typeof v==='number'&&Number.isFinite(v);

export function mountFarmDesign(root,lang='zh'){
 installOriginalLanguageSync();
 if(active?.root===root)return;
 let saved;try{saved=JSON.parse(localStorage.getItem(STORAGE)||'null');}catch{}
 const state=memory||{tab:'overview',table:'RCR',row:0,document:saved?.document||null,plans:saved?.plans||[],originalSession:saved?.originalSession||null,result:null,catalog:null,capability:null,error:'',message:'',busy:false,revision:0,calculatedRevision:-1,job:null,timer:null,search:null,selected:null,module:'Budget',filter:'',rawDraft:null,options:{population:36,generations:24,F:.15,CR:.85},variables:null,objectives:[],constraints:[]};
 if(!memory&&saved?.document&&!saved?.workbench){Object.assign(state,{...(()=>{const wb=nativeWorkbench(saved.document);return {variables:wb.variables,objectives:wb.objectives,constraints:wb.constraints,options:wb.settings};})()});}
 if(!memory&&saved?.workbench){state.variables=saved.workbench.variables;state.objectives=saved.workbench.objectives||[];state.constraints=saved.workbench.constraints||[];state.options={...state.options,...saved.workbench.settings};}
 state.catalog||={cases:[],columns:{},fieldMap:{},labels:{}};
 const controller=new AbortController();let closed=false,loadSequence=0,rendering=false,renderAgain=false;
 const t=(zh,en)=>rememberPair(zh,en,lang);
 const label=p=>t(...p);
 const action=(key,text,css='',disabled=false)=>`<button type="button" data-fd-action="${key}" class="${css}" ${disabled||usesStaticHosting()&&['calculate','optimize','export-native','apply-candidate'].includes(key)?'disabled':''}>${text}</button>`;
 function hostedNotice(){return usesStaticHosting()?`<section class="fd-panel fd-hosted-notice" data-fd-hosted><h2>${t('在线预览与 Windows 便携版','Online preview and Windows portable app')}</h2><p>${t('在线可浏览案例、编辑输入并导出项目 JSON。原版核算、优化、XML 交换和两种原版界面，请在 Windows 便携版中使用。可将此处导出的 JSON 导入便携版继续。','Browse cases, edit inputs and export project JSON online. Use the Windows portable app for original calculations, optimization, XML exchange and both original interfaces. Import the exported JSON there to continue.')}</p><div class="fd-buttons"><a href="${PORTABLE_DOWNLOAD}" data-fd-download>${t('下载 Windows 便携版 v0.3.26','Download Windows portable app v0.3.26')}</a><a href="${PORTABLE_RELEASE}" target="_blank" rel="noopener">${t('使用说明与校验值','Instructions and checksum')}</a></div></section>`:'';}
 const stale=()=>state.calculatedRevision!==state.revision;
 const persist=()=>{try{localStorage.setItem(STORAGE,JSON.stringify({document:state.document,plans:state.plans,originalSession:state.originalSession,workbench:{variables:state.variables,objectives:state.objectives,constraints:state.constraints,settings:state.options}}));return true;}catch{state.error=t('本地存储不足，请立即导出项目。','Local storage failed. Export the project now.');return false;}};
 const setMessage=s=>{state.message=s;state.error='';};
 const mutable=()=>!state.busy&&!state.job;
 function changed(){state.revision++;state.error='';state.search=null;state.selected=null;state.rawDraft=null;persist();}
 function currentResult(){return state.selected?.result||state.result;}
 function projectDocument(){const doc=clone(state.document);doc.workbench={variables:clone(variables()),objectives:clone(state.objectives),constraints:clone(state.constraints),settings:clone(state.options)};doc.optimization.variables=withNativeIds(clone(variables()).map(v=>({...v,CasID:doc.farmId})),'DvrID',doc.optimization.variables||[]);const outcomes=new Map(doc.optimization.indicators.map(o=>[[o.EntityType,o.ObjName,o.Variable].join(':'),{...o,Objective:false,Constrain:false}]));const get=key=>{if(!outcomes.has(key)){const first=key.indexOf(':'),last=key.lastIndexOf(':');outcomes.set(key,{Description:key,EntityType:key.slice(0,first),ObjName:key.slice(first+1,last),Variable:key.slice(last+1),Weight:0,Original:0,Objective:false,Direction:1,Constrain:false,Minimum:0,Maximum:0});}return outcomes.get(key);};for(const o of state.objectives)Object.assign(get(o.key),{Objective:true,Direction:o.direction==='max'?1:-1});for(const c of state.constraints){const target=get(c.key);target.Minimum=target.Constrain?Math.max(target.Minimum,c.min??-1e30):c.min??-1e30;target.Maximum=target.Constrain?Math.min(target.Maximum,c.max??1e30):c.max??1e30;target.Constrain=true;}doc.optimization.indicators=withNativeIds([...outcomes.values()].map(o=>({...o,CasID:doc.farmId})),'OuvID',doc.optimization.referenceIndicators||[]);Object.assign(doc.optimization.settings,{Amplitude:state.options.F,Probability:state.options.CR,MultiFactor:state.options.population,Generations:state.options.generations});return doc;}
 function restoreWorkbench(doc){const wb=nativeWorkbench(doc);state.variables=clone(wb.variables);state.objectives=clone(wb.objectives||[]);state.constraints=clone(wb.constraints||[]);state.options={population:36,generations:24,F:.15,CR:.85,...wb.settings};}

 function fdAttachments(){const data=state.document?.functionalDiversity||{};return `<section class="fd-panel"><h2>${t('营养功能多样性资料','Nutritional functional diversity inputs')}</h2><p>${t('原版 NFD 需要营养性状树及产品映射。没有资料时标为未配置，不把原版返回的零解释为营养多样性为零。','Native NFD requires a nutritional trait tree and product mapping. Without these data the score is unconfigured; a native zero is not interpreted as zero diversity.')}</p><div class="fd-field-grid">${[['dendrogram','性状树','Dendrogram'],['mapping','产品映射','Product mapping'],['products','产品名称','Product names']].map(([key,zh,en])=>`<label><span>${t(zh,en)}</span><span class="fd-file">${t('选择文本文件','Choose text file')}<input type="file" data-fd-attachment="${key}" aria-label="${t(zh,en)}" accept=".txt,.tsv"></span><small>${data[key]?t('已载入','Loaded')+' · '+data[key].split('\n').filter(Boolean).length+' '+t('行','lines'):t('未配置','Not configured')}</small></label>`).join('')}</div><p>${t('Mapping 两列：100000 + 作物产品ID（或 200000 + 畜产品ID），及从零开始的性状树物种行。全部文本使用制表符分隔。','Mapping columns: 100000 + crop product ID (or 200000 + animal product ID), then the zero-based species row. Use tab-delimited text.')}</p>${action('clear-fd',t('清除 NFD 资料','Clear NFD inputs'))}</section>`;}
 function advancedSettings(){const mode=state.document.runtimeOptions?.networkMetrics||'Simple';return `<section class="fd-panel"><h2>${t('流网络计算','Flow-network calculation')}</h2><label>${t('原版网络模式','Original network mode')} <select id="fd-network-mode">${[['Simple','整场简化网络','Whole-farm simple network'],['Complex','活动细分网络','Activity-level complex network'],['None','不计算网络指标','Disable network metrics']].map(([value,zh,en])=>`<option value="${value}" ${value===mode?'selected':''}>${t(zh,en)}</option>`).join('')}</select></label><p>${t('原版 DLL 保持不变。运行副本的资源索引已适配新增的四项效率比率，这些比率不进入物质流矩阵。','Original DLLs remain unchanged. Copied resource indices accommodate four appended efficiency ratios; ratios are excluded from the material-flow matrix.')}</p></section>`;}

 function metricOptions(value){const usable=(state.result?.metrics||[]).filter(m=>m.native&&isNumber(m.value));return (value&&!usable.some(m=>m.key===value)?`<option value="${esc(value)}" selected disabled>${t('原版指标暂不可用，请核对对象与所需资料','Original indicator unavailable; check its object and required inputs')} · ${esc(value)}</option>`:'')+usable.map(m=>`<option value="${esc(m.key)}" ${m.key===value?'selected':''}>${esc(metricLabel(m,lang,state.catalog))}${m.unit?' / '+esc(m.unit):''}</option>`).join('');}
 function title(){return `<div class="fd-title"><div><p class="fd-kicker">FarmDESIGN 4.21.5</p><h1>${t('农场系统设计','Whole-farm system design')}</h1><p>${t('定义生产活动与产品用途，解释资源流，在多目标之间设计可行方案。','Define activities and product destinations, explain resource flows, and design feasible alternatives across objectives.')}</p></div><div class="fd-engine ${state.capability?.ready?'ready':''}" id="fd-engine-state"><i></i>${state.capability?.ready?t('原版引擎 · 本地计算','Original engine · local computation'):t('连接本地引擎','Connecting local engine')}</div></div>`;}
 function toolbar(){const d=state.document,info=d?describeFarm(d):null;return `<div class="fd-toolbar"><label>${t('案例 / 项目','Case / project')}<select id="fd-case" ${!mutable()?'disabled':''}>${d&&!state.catalog?.cases.some(c=>c.farmId===d.farmId)?`<option value="${d.farmId}" selected>${esc(d.tables.FRM[0].Name)}</option>`:''}${(state.catalog?.cases||[]).map(c=>`<option value="${c.farmId}" ${c.farmId===d?.farmId?'selected':''}>${esc(c.farmId===d?.farmId?d.tables.FRM[0].Name:c.tables.FRM[0].Name)}</option>`).join('')}</select></label><span class="fd-case-meta">${info?`${fmt(info.area,3)} ha · ${info.crops} ${t('作物活动','crop activities')} · ${esc(info.currency)}`:''}</span><div class="fd-toolbar-actions">${action('calculate',state.busy?t('计算中…','Calculating…'):t('重新核算','Recalculate'),'primary',!d||!mutable())}${action('new-project',t('新建项目','New project'),'',!d||!mutable())}${action('export-project',t('导出项目','Export project'),'',!d)}<label class="fd-file">${t('导入项目','Import project')}<input type="file" id="fd-import" accept=".json,.xml" ${!mutable()?'disabled':''}></label></div></div>`;}
 function tabs(){return `<nav class="fd-tabs" aria-label="${t('FarmDESIGN 功能','FarmDESIGN functions')}">${[['overview','系统总览','System'],['inputs','活动与参数','Activities & inputs'],['explain','完整核算','Explain'],['optimize','多目标优化','Optimize'],['plans','方案与比较','Plans & compare'],['original','原版界面','Original interface'],['sources','来源与模型','Sources & model']].map(([key,zh,en])=>`<button data-fd-tab="${key}" aria-selected="${state.tab===key}" class="${state.tab===key?'active':''}">${t(zh,en)}${key==='plans'&&state.plans.length?` <small>${state.plans.length}</small>`:''}</button>`).join('')}</nav>`;}
 function messages(){const translated=messageLabel(state.error,lang),known=translated!==state.error||!state.error||/[\u3400-\u9fff]/u.test(translated)&&lang==='zh';const error=known?esc(translated):`${t('操作未完成，请检查输入或本地计算服务。','Operation failed. Check the inputs or local calculation service.')}<details><summary>${t('原始错误详情','Original error details')}</summary><pre>${esc(state.error)}</pre></details>`;return `${state.error?`<div class="fd-alert error" id="fd-error" role="alert">${error}</div>`:''}${state.message?`<div class="fd-alert" role="status">${esc(messageLabel(state.message,lang))}</div>`:''}${state.result&&stale()?`<div class="fd-alert warning" id="fd-stale">${t('输入已改变。当前核算属于上一版输入，重新核算后再优化或保存。','Inputs changed. These results belong to the previous input; recalculate before optimization or saving.')}</div>`:''}`;}
 function metricsPanel(result){const metrics=result?.metrics||[];const selected=[['Budget.FreeBudget','可支配预算','Disposable budget'],['EconResults.OperatingProfit','农场经营利润','Operating profit'],['OmBalance.Balance','有机质年度平衡','Annual OM balance'],['Labour.HouseholdLeisureTime','家庭休闲时间','Household leisure'],['GHGs.TotalEmissionCO2eq','温室气体排放','GHG emissions']];return `<div class="fd-metrics">${selected.map(([key,zh,en])=>{const m=metrics.find(m=>m.key===key&&isNumber(m.value));return m?`<div><span>${t(zh,en)}</span><strong>${fmt(m.value,2)}</strong><small>${esc(unitLabel(m.unit,lang))}</small></div>`:'';}).join('')}</div>`;}
 function overview(){const d=state.document;if(!d)return `<div class="fd-empty">${t('正在读取作者案例与本地引擎。','Loading author cases and local engine.')}</div>`;const info=describeFarm(d);return `${metricsPanel(currentResult())}<section class="fd-system"><div class="fd-section-heading"><h2>${t('生产、资源和家庭，是一个相连的系统','Production, resources and household form one system')}</h2><span>${t('年度静态核算','Annual steady-state accounting')}</span></div><div class="fd-flow">${[['投入与环境','Inputs & environment','FRT','土壤、肥料、水、购入饲料','Soil, fertilizer, water, purchased feed'],['作物与轮作','Crops & rotations','RCR',`${info.crops} 个作物活动 · ${fmt(info.area,3)} ha`,`${info.crops} crop activities · ${fmt(info.area,3)} ha`],['畜群与粪肥','Herds & manure','ANM',`${info.animals} 头 · 饲料、产品和回田`,`${info.animals} head · feed, products and recycling`],['经营与家庭','Farm & household','HHD','劳动、营养和可支配预算','Labour, nutrition and disposable budget']].map(([zh,en,table,note,enNote],i)=>`<button class="fd-flow-node" data-fd-table="${table}"><span>${t(zh,en)}</span><b>${t(note,enNote)}</b>${i<3?'<em aria-hidden="true">→</em>':''}</button>`).join('')}</div><p class="fd-flow-note">${t('产品可流向饲喂、还田、家庭、垫料、焚烧、燃料和厌氧消化，差额形成进出口。原版计算同时核对饲料、粪肥和资源约束。','Products flow to feed, soil, household, bedding, burning, fuel and digestion; balances determine trade. The original model evaluates feed, manure and resource constraints together.')}</p></section><div class="fd-two"><section class="fd-panel"><h2>${t('当前系统组成','Current system')}</h2><div class="fd-inventory">${Object.entries(TABLES).filter(([key])=>!['DRI','DRF'].includes(key)).map(([key,n])=>`<button data-fd-table="${key}"><span>${label(n)}</span><b>${d.tables[key]?.length||0}</b></button>`).join('')}</div></section><section class="fd-panel"><h2>${t('核算与约束','Calculation and constraints')}</h2>${state.result?statusPanel(state.result):`<p>${t('选择案例或编辑参数后，点击重新核算。','Select a case or edit inputs, then recalculate.')}</p>`}<p class="fd-provenance">${t('当前初始案例来自 Ditzler 等（2019）公开的越南案例，不是海南实测资料。','Initial cases are author-supplied Vietnam examples from Ditzler et al. (2019), not observed data from Hainan.')}</p>${action('go-optimize',t('设置设计变量与目标','Set design variables and objectives'))}</section></div>`;}
 function statusPanel(result){const violations=result.violations||[];return `<p class="fd-status ${violations.length?'invalid':'valid'}">${violations.length?`${violations.length} ${t('项约束未满足','violated constraints')}`:t('当前启用的约束均满足','All enabled constraints satisfied')}</p>${violations.length?`<ul class="fd-violations">${violations.map(v=>`<li>${esc(metricLabel(v,lang,state.catalog))}: ${esc(v.value)} ${esc(unitLabel(v.unit,lang))} <small>[${esc(v.minimum)} … ${esc(v.maximum)}]</small></li>`).join('')}</ul>`:''}${result.warnings?.length?`<ul class="fd-violations">${result.warnings.map(v=>`<li>${esc(v.startsWith('Nutritional functional diversity is not configured')?t('营养功能多样性未配置：请在“来源与模型”载入三份性状树资料；原版返回的零不视为实际 NFD 分数。','NFD is unconfigured. Load the three trait-tree files under Sources & model; the native zero is not an estimated score.'):messageLabel(v,lang))}</li>`).join('')}</ul>`:''}`;}

 function fieldMarkup(table,key){const [zh,en]=fieldPair(table,key,state.catalog),unit=isFraction(table,key,state.catalog)?'%':fieldUnit(table,key,state.catalog);return `<span class="fd-field-label">${lang==='both'?`<span>${esc(zh)}</span><small class="fd-field-english">${esc(en)}</small>`:esc(lang==='en'?en:zh)}</span>${unit?`<small class="fd-field-unit">${esc(unitLabel(unit,lang))}</small>`:''}${state.showCodes?`<small class="fd-native-code">${esc(key)}</small>`:''}`;}
 function variableLabel(variable){const [table,map]=Object.entries(state.catalog.fieldMap||{}).find(([,m])=>m.entityType===variable.EntityType)||[];const field=Object.entries(map?.properties||{}).find(([,p])=>p===variable.Variable)?.[0]||variable.Variable;const row=state.document.tables[table]?.find(r=>r[map.primaryKey]===variable.ObjID);const [zh,en]=fieldPair(table,field,state.catalog);return `${row?.Name||variable.ObjID} · ${t(zh,en)}`;}
 function inputValue(table,index,key,value){if(structuredKind(table,key,value))return structuredInput(table,key,value,state.document,lang);const pk=ID_FIELDS[table];if(key===pk||key==='FrmID')return `<output>${esc(value)}</output>`;if(typeof value==='boolean')return `<input type="checkbox" data-fd-field="${esc(key)}" ${value?'checked':''}>`;const ref=REF[key];if(ref)return `<select data-fd-field="${key}">${(state.document.tables[ref[0]]||[]).map(r=>`<option value="${r[ref[1]]}" ${r[ref[1]]===value?'selected':''}>${esc(r.Name||r[ref[1]])} (${r[ref[1]]})</option>`).join('')}</select>`;const meta=state.catalog?.columns[table]?.find(c=>c.name===key),numeric=typeof value==='number'||meta?.type?.match(/Double|Int/);if(numeric)return `<input type="number" step="any" data-fd-field="${esc(key)}" value="${esc(isFraction(table,key,state.catalog)&&typeof value==='number'?value*100:value??'')}" ${isFraction(table,key,state.catalog)?'data-fd-percent min="0" max="100"':''} ${!mutable()?'disabled':''}>`;return `<${String(value??'').length>120?'textarea':'input'} ${String(value??'').length>120?'':'type="text"'} data-fd-field="${esc(key)}" ${String(value??'').length>120?'':`value="${esc(value??'')}"`} ${!mutable()?'disabled':''}>${String(value??'').length>120?esc(value??''):''}${String(value??'').length>120?'</textarea>':''}`;}
 function inputs(){const table=state.table,rows=state.document?.tables[table]||[],r=rows[state.row]||rows[0];return `<div class="fd-editor"><aside class="fd-table-nav">${GROUPS.map(group=>`<div>${group.map(key=>`<button data-fd-table="${key}" class="${key===table?'active':''}">${label(TABLES[key])}<small>${state.document.tables[key]?.length||0}</small></button>`).join('')}</div>`).join('')}</aside><div class="fd-editor-body"><div class="fd-section-heading"><div><h2>${label(TABLES[table])}</h2><p>${t('保留原版字段名和参数单位。修改只写入本地项目。','Native field names and units are retained. Edits stay in the local project.')}</p></div>${action('show-codes',state.showCodes?t('隐藏原版代码','Hide native codes'):t('显示原版代码','Show native codes'))}<span class="fd-table-code">${table}</span></div><div class="fd-record-toolbar"><select id="fd-row">${rows.map((row,i)=>`<option value="${i}" ${row===r?'selected':''}>${esc(row.Name||row.SoilType||row.FoodGroup||row[ID_FIELDS[table]])}</option>`).join('')}</select>${action('add-row',t('新增记录','Add record'),'',!mutable())}${action('delete-row',t('删除','Delete'),'',!r||!mutable()||['FRM','ENV','ECN'].includes(table))}</div>${r?`<div class="fd-field-grid">${Object.entries(r).map(([key,value])=>{const tag=structuredKind(table,key,value)?'div':'label';return `<${tag} class="${tag==='div'?'fd-field-wide':''}" data-fd-label="${esc(key)}" title="${t('原版字段','Native field')}: ${esc(key)}">${fieldMarkup(table,key)}${inputValue(table,state.row,key,value)}${inputHelpMarkup(table,key,state.catalog,lang)}</${tag}>`;}).join('')}</div>`:`<div class="fd-empty">${t('此表目前没有记录。新增一条后配置其属性。','No records in this table. Add a record to configure it.')}</div>`}<details class="fd-advanced"><summary>${t('完整项目 JSON 与批量编辑','Full project JSON and bulk editing')}</summary><textarea id="fd-json" spellcheck="false">${esc(state.rawDraft??JSON.stringify(state.document,null,2))}</textarea>${action('apply-json',t('验证并应用项目','Validate and apply project'))}<p>${t('JSON 是本工作台的无损数据容器；原版 XML 使用专门的导入和导出按钮。','JSON is this workbench’s lossless data container. Use dedicated controls for native XML.')}</p></details></div></div>`;}
 function renderValue(value){const rows=flatten(value);return `<div class="fd-table-scroll"><table class="fd-results-table"><thead><tr><th>${t('原版结果 / 路径','Native result / path')}</th><th>${t('值','Value')}</th></tr></thead><tbody>${rows.filter(r=>!state.filter||r.path.toLowerCase().includes(state.filter.toLowerCase())).map(r=>`<tr><td>${esc(pathLabel(r.path,lang,state.catalog))}${state.showCodes?`<small class="fd-native-code">${esc(r.path)}</small>`:''}</td><td class="${typeof r.value==='number'?'numeric':''}">${r.value===null?`<span class="fd-null">${t('无值 / 不适用','Unavailable / not applicable')}</span>`:typeof r.value==='number'?fmt(r.value,6):esc(r.value)}</td></tr>`).join('')}</tbody></table></div>`;}
 function explain(){const result=currentResult();if(!result)return `<div class="fd-empty">${t('先运行一次核算，再查看全部模块和原版指标。','Calculate first to inspect all modules and native indicators.')}</div>`;const modules=Object.keys(MODULES).filter(k=>result.modules&&Object.hasOwn(result.modules,k));return `${metricsPanel(result)}${state.selected?`<div class="fd-buttons">${action('apply-candidate',t('应用为当前设计','Apply as current design'),'primary')}${action('save-plan',t('保存此方案','Save this alternative'))}</div>`:''}<div class="fd-explain"><aside>${modules.map(k=>`<button data-fd-module="${k}" class="${state.module===k?'active':''}">${label(MODULES[k])}</button>`).join('')}<button data-fd-module="metrics" class="${state.module==='metrics'?'active':''}">${t('全部指标与单位','All indicators & units')}</button><button data-fd-module="constraints" class="${state.module==='constraints'?'active':''}">${t('约束检查','Constraint checks')}</button></aside><section class="fd-panel"><div class="fd-section-heading"><h2>${MODULES[state.module]?label(MODULES[state.module]):state.module==='metrics'?t('全部原版指标','All native indicators'):t('启用约束','Enabled constraints')}</h2>${action('show-codes',state.showCodes?t('隐藏原版代码','Hide native codes'):t('显示原版代码','Show native codes'))}${action('export-csv',t('导出 CSV','Export CSV'))}</div><label class="fd-filter">${t('查找结果字段','Filter result fields')}<input id="fd-result-filter" value="${esc(state.filter)}"></label>${state.module==='constraints'?statusPanel(result):state.module==='metrics'?`<div class="fd-table-scroll"><table><thead><tr><th>${t('指标','Indicator')}</th><th>${t('值','Value')}</th><th>${t('单位','Unit')}</th></tr></thead><tbody>${(result.metrics||[]).filter(m=>!state.filter||(m.key+' '+metricLabel(m,'both',state.catalog)).toLowerCase().includes(state.filter.toLowerCase())).map(m=>`<tr><td>${esc(metricLabel(m,lang,state.catalog))}${state.showCodes?`<small class="fd-native-code">${esc(m.key)}</small>`:''}</td><td>${isNumber(m.value)?fmt(m.value,5):esc(m.value??'—')}</td><td>${esc(unitLabel(m.unit,lang))}</td></tr>`).join('')}</tbody></table></div>`:renderValue(result.modules?.[state.module]||{})}</section></div>`;}
 function variables(){return state.variables||state.document.optimization?.variables||[];}
 function optimize(){const vars=variables(),search=state.search,options=state.options;return `<div class="fd-optimize"><section class="fd-panel"><div class="fd-section-heading"><div><h2>${t('设计变量','Design variables')}</h2><p>${t('可改变的原版属性、范围和精确约束','Native adjustable properties, bounds and exact constraints')}</p></div>${action('add-variable',t('添加变量','Add variable'),'',!mutable())}</div><div class="fd-table-scroll"><table class="fd-variable-table"><thead><tr><th>${t('变量','Variable')}</th><th>${t('下限','Minimum')}</th><th>${t('上限','Maximum')}</th><th></th></tr></thead><tbody>${vars.map((v,i)=>`<tr><td>${esc(variableLabel(v))}<details class="fd-exact"><summary>${t('精确约束','Exact constraint')}</summary><label><input type="checkbox" data-fd-exact="${i}" ${v.ExactUse?'checked':''}>${t('启用','Enable')}</label><label>${t('目标值','Target')}<input type="number" step="any" data-fd-exact-value="${i}" data-key="ExactValue" value="${v.ExactValue??0}"></label><label>${t('容许偏差','Tolerance')}<input type="number" step="any" data-fd-exact-value="${i}" data-key="ExactDeviation" value="${v.ExactDeviation??0}"></label></details>${state.showCodes?`<small class="fd-native-code">${esc(v.EntityType)} · ${esc(v.ObjID)} · ${esc(v.Variable)}</small>`:''}</td><td><input type="number" step="any" data-fd-variable="${i}" data-key="Minimum" value="${v.Minimum}" ${!mutable()?'disabled':''}></td><td><input type="number" step="any" data-fd-variable="${i}" data-key="Maximum" value="${v.Maximum}" ${!mutable()?'disabled':''}></td><td><button data-fd-remove-variable="${i}" ${!mutable()?'disabled':''}>×</button></td></tr>`).join('')}</tbody></table></div><details class="fd-advanced"><summary>${t('新增变量的对象和属性','Object and property for a new variable')}</summary><label>${t('数据表','Table')}<select id="fd-var-table">${Object.keys(TABLES).filter(k=>!['DRI','DRF'].includes(k)).map(k=>`<option value="${k}" ${k==='RCR'?'selected':''}>${label(TABLES[k])}</option>`).join('')}</select></label><label>${t('记录 ID','Record ID')}<input id="fd-var-id" type="number" value="${state.document.tables.RCR?.[0]?.RcrID||0}"></label><label>${t('数值字段名','Numeric field name')}<input id="fd-var-field" value="Area"></label><p>${t('点击“添加变量”，会验证该对象和属性存在且可以设置。','Add variable verifies that the object and numeric property exist and are writable.')}</p></details></section><section class="fd-panel"><h2>${t('目标与资源约束','Objectives & resource constraints')}</h2><p>${t('原版模型核算每个候选，保留可行非支配方案；搜索结果相对于实际评估的候选集。','The original model evaluates every candidate. Feasible non-dominated alternatives are retained relative to the evaluated candidate set.')}</p><div id="fd-objectives">${state.objectives.map((o,i)=>`<div class="fd-objective-row"><select data-fd-objective="${i}" data-key="key">${metricOptions(o.key)}</select><select data-fd-objective="${i}" data-key="direction"><option value="max" ${o.direction==='max'?'selected':''}>${t('最大化','Maximize')}</option><option value="min" ${o.direction==='min'?'selected':''}>${t('最小化','Minimize')}</option></select><button data-fd-remove-objective="${i}">×</button></div>`).join('')}</div>${action('add-objective',t('增加目标','Add objective'),'',!mutable())}<details class="fd-advanced"><summary>${t('附加指标约束','Additional indicator constraints')}</summary>${state.constraints.map((c,i)=>`<div class="fd-constraint-row"><select data-fd-constraint="${i}" data-key="key">${metricOptions(c.key)}</select><input type="number" step="any" aria-label="${t('下限','Minimum')}" data-fd-constraint="${i}" data-key="min" value="${esc(c.min??'')}"><input type="number" step="any" aria-label="${t('上限','Maximum')}" data-fd-constraint="${i}" data-key="max" value="${esc(c.max??'')}"><button data-fd-remove-constraint="${i}">×</button></div>`).join('')}${action('add-constraint',t('添加约束','Add constraint'),'',!mutable())}<p>${t('作者案例已有的原版约束始终保留；新增约束与之同时检查。','Native constraints in the author case are retained and checked together with additions.')}</p></details><div class="fd-search-settings">${[['population','原版种群参数 M','Native population parameter M'],['generations','代数','Generations'],['F','变异幅度 F','Mutation F'],['CR','交叉概率 CR','Crossover CR']].map(([k,zh,en])=>`<label>${t(zh,en)}<input type="number" step="${['F','CR'].includes(k)?'.01':'1'}" data-fd-option="${k}" value="${options[k]}" ${!mutable()?'disabled':''}></label>`).join('')}</div><div class="fd-buttons">${action('optimize',state.job?t('搜索中…','Searching…'):t('开始多目标优化','Start multi-objective search'),'primary',!state.result||stale()||!mutable())}${action('cancel-search',t('停止搜索','Stop search'),'',!state.job)}</div><div id="fd-search-progress" role="status">${state.job?`${t('已完成代数','Completed generations')} ${state.job.generation||0} · ${t('可行','Feasible')} ${state.job.feasible||0} · ${t('前沿','Frontier')} ${state.job.frontier||0}`:search?`${t('评估完成','Evaluation complete')} · ${search.generation} ${t('代','generations')} · ${(search.frontier||[]).length} ${t('非支配方案','non-dominated alternatives')}`:''}</div></section></div>${search?frontier(search):''}`;}
 function frontier(search){const front=search.frontier||[],objectives=search.objectives||state.objectives,x=objectives[0],y=objectives[1]||x;const get=(c,o)=>c.scores?.[o?.key]??0;const values=front.map(c=>[get(c,x),get(c,y)]),xs=values.map(v=>v[0]),ys=values.map(v=>v[1]);const loX=Math.min(...xs,0),hiX=Math.max(...xs,1),loY=Math.min(...ys,0),hiY=Math.max(...ys,1);return `<section class="fd-panel fd-frontier"><div class="fd-section-heading"><h2>${t('可行方案的权衡','Trade-offs among feasible alternatives')}</h2><span>${front.length} ${t('个方案','alternatives')}</span></div>${front.length?`<svg viewBox="0 0 740 280" role="img" aria-label="Pareto frontier"><path d="M70 20V230H720" fill="none" stroke="currentColor" opacity=".2"/><text x="70" y="263">${esc(x?.key)}</text><text x="70" y="14">${esc(y?.key)}</text>${front.map((c,i)=>`<circle cx="${70+(get(c,x)-loX)/(hiX-loX)*630}" cy="${225-(get(c,y)-loY)/(hiY-loY)*190}" r="${state.selected?.id===c.id?7:4}" tabindex="0" role="button" aria-label="${esc(c.id)}" data-fd-candidate="${i}"><title>${esc(c.id)}: ${fmt(get(c,x),2)}, ${fmt(get(c,y),2)}</title></circle>`).join('')}</svg><div class="fd-table-scroll"><table><thead><tr><th>${t('方案','Alternative')}</th>${objectives.map(o=>`<th>${esc(metricLabel(o,lang,state.catalog))}</th>`).join('')}<th></th></tr></thead><tbody>${front.map((c,i)=>`<tr class="${state.selected?.id===c.id?'selected':''}"><td>${esc(c.id)}</td>${objectives.map(o=>`<td>${fmt(get(c,o),3)}</td>`).join('')}<td><button data-fd-candidate="${i}">${t('查看核算','Inspect')}</button></td></tr>`).join('')}</tbody></table></div>`:`<p>${t('尚未找到满足全部约束的方案。检查可变范围、原版约束或增加搜索预算；这不构成全局不可行证明。','No feasible alternative was found. Check bounds and native constraints or increase the search budget; this does not prove global infeasibility.')}</p>`}</section>`;}
 function plans(){return `<div class="fd-section-heading"><div><h2>${t('保存、复核与比较','Save, verify and compare')}</h2><p>${t('保存当前完整输入、原版计算输出和内容摘要；导入时重新计算，不信任旧输出。','Save complete inputs, native outputs and content digests. Imported runs are recalculated rather than trusting saved outputs.')}</p></div>${action('save-plan',t('保存当前方案','Save current plan'),'primary',!currentResult()||stale()||!mutable())}</div>${state.plans.length?`<div class="fd-plan-list">${state.plans.map((p,i)=>`<article class="fd-panel"><h3>${esc(p.name)}</h3><p>${esc(p.savedAt)} · ${esc(p.document.tables.FRM[0].Name)}</p><code>${esc(p.inputDigest?.slice(0,16)||'')}</code><div class="fd-buttons"><button data-fd-load-plan="${i}">${t('恢复并核算','Restore & calculate')}</button><button data-fd-export-plan="${i}">${t('导出运行记录','Export run')}</button><button data-fd-delete-plan="${i}">${t('删除','Delete')}</button></div></article>`).join('')}</div>${comparePlans()}`:`<div class="fd-empty">${t('先核算一个系统或选中优化方案，再保存。','Calculate a system or select an optimized alternative, then save it.')}</div>`}<div class="fd-buttons">${action('save-plan',t('保存当前方案','Save current plan'),'',!currentResult()||stale()||!mutable())}${action('export-native',t('导出原版 XML','Export native XML'),'',!state.document||!mutable())}${action('export-package',t('导出完整原生项目包','Export complete native project'),'',!state.document||!mutable())}</div>`;}
 function comparePlans(){if(state.plans.length<2)return '';const chosen=state.plans.slice(-2),keys=[...new Set(chosen.flatMap(p=>(p.result.metrics||[]).filter(m=>isNumber(m.value)).map(m=>m.key)))];return `<section class="fd-panel fd-comparison"><h2>${t('最近两个方案逐项比较','Compare the two latest saved plans')}</h2>${chosen[0].document.farmId!==chosen[1].document.farmId?`<p class="fd-alert warning">${t('两方案属于不同案例，仅可描述性对照。','These plans belong to different cases; comparisons are descriptive only.')}</p>`:''}<div class="fd-table-scroll"><table><thead><tr><th>${t('指标','Indicator')}</th>${chosen.map(p=>`<th>${esc(p.name)}</th>`).join('')}<th>Δ</th></tr></thead><tbody>${keys.map(key=>{const a=chosen[0].result.metrics.find(m=>m.key===key),b=chosen[1].result.metrics.find(m=>m.key===key);return `<tr><td>${esc(metricLabel(a||b||{key},lang,state.catalog))} <small>${esc(unitLabel(a?.unit||b?.unit,lang))}</small></td><td>${a&&isNumber(a.value)?fmt(a.value,4):'—'}</td><td>${b&&isNumber(b.value)?fmt(b.value,4):'—'}</td><td>${a&&b&&isNumber(a.value)&&isNumber(b.value)?fmt(b.value-a.value,4):'—'}</td></tr>`;}).join('')}</tbody></table></div></section>`;}
 function sources(){return `${advancedSettings()}${fdAttachments()}<section class="fd-panel fd-source"><h2>${t('原版模型及其来源','Original model and provenance')}</h2><p>${t('本工作台通过本地服务调用作者 FarmDESIGN 4.21.5 的 FarmSimulation 计算类，计算数据来自当前编辑的项目。原始作者程序与数据库保留，运行副本和项目分别保存。','This workbench calls the author’s FarmDESIGN 4.21.5 FarmSimulation class through a local service using the current edited project. Original author software and databases are preserved; runtime copies and projects are stored separately.')}</p><ul><li><a href="https://doi.org/10.1016/j.agsy.2012.03.012" target="_blank" rel="noopener">Groot, Oomen & Rossing (2012) · ${t('农场系统多目标优化与设计','Multi-objective optimization and design of farming systems')}</a></li><li><a href="https://doi.org/10.1016/j.agsy.2019.02.008" target="_blank" rel="noopener">Ditzler et al. (2019) · ${t('农场与家庭模块扩展','Farm and household extensions')}</a></li><li><a href="https://doi.org/10.17632/n3sk27ggwf.1" target="_blank" rel="noopener">${t('作者软件与案例归档 · CC BY 4.0','Author software and example archive · CC BY 4.0')}</a></li><li><a href="./docs/FARMDESIGN_SOURCE_SPEC.md" target="_blank" rel="noopener">${t('原手册逐项功能与实现说明','Manual-based feature and implementation specification')}</a></li></ul><h3>${t('模型与使用边界','Model scope')}</h3><p>${t('原版是年度静态、稳态的目标产量核算模型。作物、饲料和管理系数应有独立来源；此处的核算成功不代表海南实证校准或管理措施已被验证。所有原版指标、非有限值和约束均保留显示。','The original model uses annual static, steady-state, target-yield accounting. Crop, feed and management parameters require independent sources; successful computation does not establish empirical calibration for Hainan. Native indicators, non-finite results and constraints remain visible.')}</p><p>${t('本地计算不需要互联网，但需要保持本机 Farm 服务开启。A/B 与地图的浏览器离线能力继续保留。','Native computation needs no internet, but the local Farm service must stay running. Existing browser-offline A/B and map functions are preserved.')}</p><h3>${t('程序身份','Software identity')}</h3><pre>${esc(JSON.stringify(state.capability?.identity||{},null,2))}</pre><h3>${t('参数口径','Parameter conventions')}</h3><p>${t('产品 N/P/K 和灰分为干物质百分比；食品营养多为每 100 g 鲜重；作物用途为 kg DM，畜产品用途为 kg 鲜重；劳动为小时，金额保持项目货币。P/K 均为元素量，不能直接输入 P₂O₅/K₂O。','Product N/P/K and ash use dry-matter percentages; food composition mostly uses per 100 g fresh matter. Crop destinations use kg DM, animal destinations kg fresh matter, labour uses hours, and amounts retain the project currency. P/K are elemental, not P₂O₅/K₂O.')}</p></section>`;}
 function render(){if(closed)return;closeOriginalUi();if(rendering){renderAgain=true;return;}rendering=true;try{const content=!state.document?overview():({overview,inputs,explain,optimize,plans,sources,original:()=>'<section id="fd-original-root"></section>'})[state.tab]();root.innerHTML=`<div class="fd-workbench">${title()}${hostedNotice()}${toolbar()}${tabs()}${messages()}<div class="fd-content">${content}</div></div>`;}finally{rendering=false;const originalRoot=root.querySelector('#fd-original-root');if(originalRoot&&usesStaticHosting())originalRoot.innerHTML=`<section class="fd-panel"><h2>${t('使用原版界面','Use the original interfaces')}</h2><p>${t('下载上方 Windows 便携版后，可以选择“在浏览器中打开原版”或“打开原版软件窗口”。两种入口使用同一份项目数据库。','Download the Windows portable app above, then choose the original browser interface or desktop window. Both use the same project database.')}</p></section>`;if(originalRoot&&!usesStaticHosting())mountOriginalUi(originalRoot,{language:lang,catalog:state.catalog,getDocument:projectDocument,getSession:()=>state.originalSession,setSession:(value,farmId)=>{if(farmId!==undefined&&farmId!==state.document?.farmId)return;state.originalSession=value;persist();},onImport:async doc=>{const issues=validateDocument(doc);if(issues.length)throw Error(issues.join('\n'));state.document=doc;restoreWorkbench(doc);changed();state.tab='inputs';state.table='FRM';state.row=0;render();await calculate();}});if(renderAgain){renderAgain=false;queueMicrotask(render);}}}
 function setTable(table){state.table=table;state.row=0;state.tab='inputs';state.filter='';render();}
 async function calculate(doc=state.document){const issues=validateDocument(doc);if(issues.length)throw Error(issues.slice(0,12).join('\n'));state.busy=true;state.error='';render();try{const result=await request('evaluate',{document:doc,signal:controller.signal});if(closed)return;state.result=result;state.selected=null;state.calculatedRevision=state.revision;setMessage(t('已使用原版引擎重新核算当前输入。','The original engine recalculated the current inputs.'));persist();}finally{state.busy=false;render();}}
 async function loadCase(farmId){const doc=state.catalog.cases.find(c=>c.farmId===farmId);if(!doc)throw Error('Unknown case');state.document=clone(doc);state.originalSession=null;state.revision++;state.result=null;state.search=null;state.selected=null;restoreWorkbench(doc);state.rawDraft=null;state.row=0;persist();render();if(state.capability?.ready)await calculate();}
 async function poll(){if(closed||!state.job)return;try{const result=await request('jobs/'+state.job.id,{signal:controller.signal});if(closed)return;if(['completed','cancelled','failed'].includes(result.status)){state.job=null;if(result.status==='failed')throw Error(result.error||'Search failed');state.search=result;setMessage(result.status==='cancelled'?t('搜索已停止；已评估候选仍可查看。','Search stopped; evaluated alternatives remain available.'):t('搜索完成，选择方案查看其完整核算。','Search finished. Select an alternative to inspect its complete calculation.'));render();}else{state.job=result;const p=root.querySelector('#fd-search-progress');if(p)p.textContent=`${t('已完成代数','Completed generations')} ${result.generation} · ${t('可行','Feasible')} ${result.feasible} · ${t('前沿','Frontier')} ${result.frontier}`;state.timer=setTimeout(poll,700);}}catch(e){if(e.name!=='AbortError'){state.job=null;state.error=e.message;render();}}}
 async function savePlan(){if(stale()||!currentResult())throw Error(t('输入已改变，请重新计算。','Recalculate changed inputs first.'));const document=clone(state.selected?.document||projectDocument()),result=clone(currentResult()),savedAt=new Date().toISOString();const plan={schema:'FarmSystemDesign.FarmDESIGN.Run',schemaVersion:1,name:`${document.tables.FRM[0].Name} · ${state.plans.length+1}`,savedAt,document,result,inputDigest:await digest(document),resultDigest:await digest(result),engine:state.capability?.identity};state.plans.push(plan);if(persist())setMessage(t('已保存完整方案与内容摘要。','Saved complete inputs, results and content digests.'));else state.message=t('方案仍在当前窗口，请导出运行记录。','The plan remains in this window. Export its run record.');render();}
 async function handleAction(key){
  if(key==='show-codes'){state.showCodes=!state.showCodes;render();return;}
  if(key==='calculate')return calculate();
  if(key==='clear-fd'){delete state.document.functionalDiversity;changed();render();return;}
  if(key==='new-project'){const doc=clone(state.document),id=doc.farmId+100000;doc.farmId=id;for(const rows of Object.values({...doc.tables,...doc.auxiliaryTables}))for(const row of rows)if('FrmID'in row)row.FrmID=id;doc.tables.FRM[0].Name=t('新农场项目','New farm project')+' '+id;for(const rows of [doc.optimization.variables,doc.workbench?.variables])for(const variable of rows||[])if(['MixedFarm','Farm'].includes(variable.EntityType)&&variable.ObjID===id-100000)variable.ObjID=id;for(const rows of [doc.optimization.variables,doc.optimization.indicators])for(const row of rows)row.CasID=id;doc.provenance={...doc.provenance,kind:'template-derived',notice:'Derived from the selected template; parameters require local verification'};state.document=doc;state.originalSession=null;state.variables=null;changed();setMessage(t('已从当前模板建立新项目。请按自己的资料修改参数，模板系数不自动成为本地实测。','Created a project from the current template. Replace parameters with your own data; template coefficients are not local observations.'));state.tab='inputs';state.table='FRM';state.row=0;render();return;}
  if(key==='apply-candidate'){if(!state.selected)throw Error('Select an alternative first');state.document=clone(state.selected.document);const result=state.selected.result;changed();state.result=result;state.calculatedRevision=state.revision;setMessage(t('该方案已成为当前设计。','This alternative is now the current design.'));render();return;}
  if(key==='export-package'){state.busy=true;render();try{const result=await request('export-package',{document:projectDocument(),signal:controller.signal});const bytes=Uint8Array.from(atob(result.base64),c=>c.charCodeAt(0));const observed=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),n=>n.toString(16).padStart(2,'0')).join('');if(observed!==result.sha256)throw Error('Package digest mismatch');download(result.filename,new Blob([bytes],{type:'application/zip'}));}finally{state.busy=false;render();}return;}
if(key==='go-optimize'){state.tab='optimize';render();return;}
  if(key==='export-project'){download('farmdesign-project.json',JSON.stringify(projectDocument(),null,2));return;}
  if(key==='export-native'){state.busy=true;render();try{const result=await request('export-xml',{document:state.document,signal:controller.signal});download('farmdesign-native.xml',result.xml,'application/xml');}finally{state.busy=false;render();}return;}
  if(key==='apply-json'){const doc=parseDocument(root.querySelector('#fd-json').value);state.document=doc;state.variables=null;changed();setMessage(t('项目已验证并应用。请重新核算。','Project validated and applied. Recalculate next.'));render();return;}
  if(key==='save-plan')return savePlan();
  if(key==='export-csv'){const result=currentResult();const rows=state.module==='metrics'?[[t('原版字段代码','Native key'),t('指标','Indicator'),t('数值','Value'),t('单位','Unit')],...result.metrics.map(m=>[m.key,metricLabel(m,lang,state.catalog),m.value,unitLabel(m.unit,lang)])]:[[t('原版路径','Native path'),t('指标','Indicator'),t('数值','Value')],...flatten(result.modules?.[state.module]||{}).map(r=>[r.path,pathLabel(r.path,lang,state.catalog),r.value])];download(`farmdesign-${state.module}.csv`,csv(rows),'text/csv;charset=utf-8');return;}
  if(key==='add-row'){const rows=state.document.tables[state.table]||=[],columns=state.catalog.columns[state.table]||[],source=rows[state.row]||rows[0],pk=ID_FIELDS[state.table];let row=source?clone(source):Object.fromEntries(columns.map(c=>[c.name,c.type==='System.String'?'':c.type==='System.Boolean'?false:0]));row[pk]=Math.max(0,...rows.map(r=>r[pk]))+1;if('FrmID'in row)row.FrmID=state.document.farmId;if('Name'in row)row.Name=(source?.Name||state.table)+' (copy)';for(const [field,[table,id]]of Object.entries(REF))if(field in row&&field!==pk&&!state.document.tables[table]?.some(r=>r[id]===row[field]))row[field]=state.document.tables[table]?.[0]?.[id]??0;rows.push(row);state.document.tables[state.table]=rows;state.row=rows.length-1;changed();render();return;}
  if(key==='delete-row'){const next=clone(state.document);next.tables[state.table].splice(state.row,1);const issues=validateDocument(next);if(issues.length)throw Error(t('该记录仍被其他表引用，请先修改对应关系。','This record is still referenced. Update related rows first.')+'\n'+issues.slice(0,4).join('\n'));state.document=next;state.row=0;changed();render();return;}
  if(key==='add-variable'){const table=root.querySelector('#fd-var-table')?.value||'RCR',id=Number(root.querySelector('#fd-var-id')?.value),field=root.querySelector('#fd-var-field')?.value||'Area',row=state.document.tables[table]?.find(r=>r[ID_FIELDS[table]]===id);if(!row||!isNumber(row[field])||field===ID_FIELDS[table]||field==='FrmID')throw Error(t('请选择已有的可编辑数值字段。','Select an existing writable numeric field.'));const types={RCR:'RotationCrop',CRP:'Crop',PRD:'CropProduct',ANM:'Animal',APR:'AnimalProduct',FRT:'Fertilizer',MAN:'Manure',HMR:'HouseholdMember',ECN:'Economics',ENV:'Environment',CFR:'CropFertilizer',CMR:'CropManure',HHD:'Household',MCH:'Machine',BLD:'Building'};const vars=clone(variables());if(vars.some(v=>v.EntityType===types[table]&&v.ObjID===id&&v.Variable===field))throw Error('Variable already selected');vars.push({EntityType:state.catalog.fieldMap?.[table]?.entityType||types[table]||table,ObjID:id,Variable:state.catalog.fieldMap?.[table]?.properties[field]||field,Description:`${row.Name||table} ${field}`,Minimum:0,Maximum:Math.max(row[field]*2,1),ExactUse:false,ExactValue:0,ExactDeviation:0});state.variables=vars;render();return;}
  if(key==='add-objective'){const key=state.result?.metrics.find(m=>m.native&&isNumber(m.value)&&!state.objectives.some(o=>o.key===m.key))?.key;if(key)state.objectives.push({key,direction:'max'});render();return;}
  if(key==='add-constraint'){const key=state.result?.metrics.find(m=>m.native&&isNumber(m.value))?.key;if(key)state.constraints.push({key,min:0,max:null});render();return;}
  if(key==='optimize'){if(stale())throw Error('Recalculate changed inputs');state.error='';state.search=null;state.selected=null;const job=await request('optimize',{document:state.document,variables:variables(),objectives:state.objectives,constraints:state.constraints,settings:state.options,signal:controller.signal});state.job=job;render();poll();return;}
  if(key==='cancel-search'){await request('cancel',{jobId:state.job.id,signal:controller.signal});setMessage(t('正在停止搜索…','Stopping search…'));return;}
 }
 async function click(event){const target=event.target.closest('[data-fd-reorder],[data-fd-action],[data-fd-tab],[data-fd-table],[data-fd-module],[data-fd-candidate],[data-fd-load-plan],[data-fd-export-plan],[data-fd-delete-plan],[data-fd-remove-variable],[data-fd-remove-objective],[data-fd-remove-constraint]');if(!target||target.disabled)return;try{const ds=target.dataset;if(ds.fdReorder){const row=state.document.tables[state.table][state.row];row[ds.fdReorder]=reorderModules(row[ds.fdReorder],Number(ds.index),Number(ds.offset));changed();render();return;}if(ds.fdTab){state.tab=ds.fdTab;render();return;}if(ds.fdTable)return setTable(ds.fdTable);if(ds.fdModule){state.module=ds.fdModule;state.filter='';render();return;}if('fdCandidate'in ds){const c=state.search.frontier[Number(ds.fdCandidate)];state.busy=true;render();try{const result=await request('evaluate',{document:c.document,signal:controller.signal});state.selected={...c,result};state.module='Budget';state.tab='explain';setMessage(t('正在查看优化方案，其输入随保存快照一起保留。','Inspecting the optimized alternative. Its inputs are retained when saved.'));}finally{state.busy=false;render();}return;}if('fdLoadPlan'in ds){state.document=clone(state.plans[Number(ds.fdLoadPlan)].document);restoreWorkbench(state.document);changed();await calculate();return;}if('fdExportPlan'in ds){download('farmdesign-run.json',JSON.stringify(state.plans[Number(ds.fdExportPlan)],null,2));return;}if('fdDeletePlan'in ds){state.plans.splice(Number(ds.fdDeletePlan),1);persist();render();return;}if('fdRemoveVariable'in ds){state.variables=clone(variables());state.variables.splice(Number(ds.fdRemoveVariable),1);render();return;}if('fdRemoveObjective'in ds){state.objectives.splice(Number(ds.fdRemoveObjective),1);render();return;}if('fdRemoveConstraint'in ds){state.constraints.splice(Number(ds.fdRemoveConstraint),1);render();return;}if(ds.fdAction)await handleAction(ds.fdAction);}catch(e){if(e.name!=='AbortError'){state.error=e.message;state.busy=false;render();}}}
 async function change(event){const el=event.target;try{if(el.dataset.fdEncoded){const row=state.document.tables[state.table][state.row],key=el.dataset.fdEncoded;row[key]=editEncoded(row[key],structuredKind(state.table,key,row[key]),Number(el.dataset.index),el.type==='checkbox'?el.checked:el.value===''?NaN:Number(el.value));changed();render();return;}if(el.id==='fd-network-mode'){state.document.runtimeOptions={networkMetrics:el.value};changed();render();return;}if(el.dataset.fdAttachment){const file=el.files[0];if(!file)return;if(file.size>1024*1024)throw Error('NFD attachment exceeds 1 MB');state.document.functionalDiversity={...(state.document.functionalDiversity||{}),[el.dataset.fdAttachment]:await file.text(),source:'User supplied trait tree; not empirically verified'};changed();render();return;}if(el.id==='fd-case'){await loadCase(Number(el.value));return;}if(el.id==='fd-row'){state.row=Number(el.value);render();return;}if(el.id==='fd-import'){const file=el.files[0];if(!file)return;if(file.size>8*1024*1024)throw Error('Project exceeds 8 MB');state.busy=true;state.error='';render();let doc;const text=await file.text();if(closed)return;if(file.name.toLowerCase().endsWith('.xml'))doc=(await request('import-xml',{xml:text,signal:controller.signal})).document;else{const raw=JSON.parse(text);if(raw.schema==='FarmSystemDesign.FarmDESIGN.Run'){if(await digest(raw.document)!==raw.inputDigest||await digest(raw.result)!==raw.resultDigest)throw Error(t('运行记录摘要不匹配，拒绝导入。','Run record digest mismatch; import rejected.'));doc=raw.document;}else doc=parseDocument(text);}if(closed)return;const issues=validateDocument(doc);if(issues.length)throw Error(issues.join('\n'));state.document=doc;restoreWorkbench(doc);changed();await calculate();return;}if(el.dataset.fdField){const row=state.document.tables[state.table][state.row],key=el.dataset.fdField,meta=state.catalog.columns[state.table]?.find(c=>c.name===key);const value=el.type==='checkbox'?el.checked:el.type==='number'||REF[key]?el.value===''?null:Number(el.value):el.value;if(meta?.type==='System.Int32'&&value!==null&&!Number.isInteger(value))throw Error(key+': integer required');row[key]=el.hasAttribute('data-fd-percent')&&value!==null?value/100:value;changed();render();return;}if(el.dataset.fdExact!==undefined){state.variables=clone(variables());state.variables[Number(el.dataset.fdExact)].ExactUse=el.checked;persist();return;}if(el.dataset.fdExactValue!==undefined){state.variables=clone(variables());state.variables[Number(el.dataset.fdExactValue)][el.dataset.key]=Number(el.value);persist();return;}if(el.dataset.fdVariable){state.variables=clone(variables());const value=Number(el.value);if(!Number.isFinite(value))throw Error('Finite bound required');state.variables[Number(el.dataset.fdVariable)][el.dataset.key]=value;persist();return;}if(el.dataset.fdObjective){state.objectives[Number(el.dataset.fdObjective)][el.dataset.key]=el.value;persist();return;}if(el.dataset.fdConstraint){state.constraints[Number(el.dataset.fdConstraint)][el.dataset.key]=el.dataset.key==='key'?el.value:el.value===''?null:Number(el.value);persist();return;}if(el.dataset.fdOption){state.options[el.dataset.fdOption]=Number(el.value);persist();}}catch(e){if(e.name!=='AbortError'){state.busy=false;state.error=e.message;render();}}}
 root.addEventListener('click',click);root.addEventListener('change',change);root.addEventListener('input',e=>{if(e.target.id==='fd-json')state.rawDraft=e.target.value;if(e.target.id==='fd-result-filter'){state.filter=e.target.value;const start=e.target.selectionStart;render();const el=root.querySelector('#fd-result-filter');el.focus();el.setSelectionRange(start,start);}});
 root.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.matches('[data-fd-candidate]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
 active={root,exportProject(){download('farmdesign-project.json',JSON.stringify(projectDocument(),null,2));},close(){closed=true;clearTimeout(state.timer);memory={...state,busy:false,timer:null};controller.abort();root.removeEventListener('click',click);root.removeEventListener('change',change);}};
 render();
 const sequence=++loadSequence;
 (async()=>{try{const [response,capability]=await Promise.all([fetch('./data/farmdesign/author-cases-2019.json').then(r=>{if(!r.ok)throw Error('Author cases unavailable');return r.json();}),request('capabilities',{signal:controller.signal}).catch(e=>({ready:false,error:e.message}))]);if(closed||sequence!==loadSequence)return;state.catalog=response;state.capability=capability;if(capability.error)state.error=capability.error;if(!state.document||validateDocument(state.document).length){await loadCase(response.cases[0].farmId);}else{render();if(state.job)poll();else if(capability.ready&&!state.result)await calculate();}}catch(e){if(e.name!=='AbortError'){state.error=e.message;render();}}})();
 return active.close;
}
export function closeFarmDesign(){closeOriginalUi();active?.close();active=null;}

export function exportFarmDesignProject(){active?.exportProject();}
